// SPDX-License-Identifier: MIT
import assert from 'node:assert/strict';
import test from 'node:test';
import { retry } from '../src/retry.mjs';

test('returns the first successful result without another attempt', async () => {
  const seen = [];
  const result = await retry(async (attempt) => {
    seen.push(attempt);
    return 'ready';
  });
  assert.equal(result, 'ready');
  assert.deepEqual(seen, [1]);
});

test('the default permits two failures before a successful third attempt', async () => {
  const seen = [];
  const result = await retry(async (attempt) => {
    seen.push(attempt);
    if (attempt < 3) throw new Error('temporary failure');
    return 'ready';
  });
  assert.equal(result, 'ready');
  assert.deepEqual(seen, [1, 2, 3]);
});

test('throws the last error object after exactly the configured attempts', async () => {
  const seen = [];
  const errors = [];
  await assert.rejects(retry(async (attempt) => {
    seen.push(attempt);
    const error = new Error(`failure ${attempt}`);
    errors.push(error);
    throw error;
  }, { attempts: 3 }), (error) => error === errors[2]);
  assert.deepEqual(seen, [1, 2, 3]);
});

test('rejects zero attempts without calling the operation', async () => {
  let called = false;
  await assert.rejects(retry(async () => {
    called = true;
  }, { attempts: 0 }), RangeError);
  assert.equal(called, false);
});
